// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Tanımlayıcı istatistik hesapları (zor).
const ozStatistics6Zor = <(String, String, List<String>, String)>[
  ('Sturges kuralındaki k = 1 + 3,322·log₁₀(n) ifadesi, 2 tabanında logaritmayla yazıldığında hangi biçimi alır?', 'k = 1 + log₂n', ['k = log₂(n) − 1', 'k = 2·log₂(n)', 'k = 1 + n/2'], '3,322 ≈ 1/log₁₀2 olduğundan 3,322·log₁₀n = log₂n olur; formül k = 1 + log₂n biçimine dönüşür.'),
  ('Bir tartıda ağırlıklar bir ondalık basamakla (ör. 2,3 kg) kaydediliyor. Frekans tablosundaki 2,0–2,4 sınıfının gerçek sınırları nedir?', '1,95 ve 2,45', ['1,5 ve 2,5', '2,0 ve 2,5', '1,90 ve 2,40'], 'Kayıt duyarlığı 0,1 olduğundan sınırlardan bu duyarlığın yarısı (0,05) kadar dışarı taşınır: 1,95 ile 2,45.'),
  ('Yaşlar \'son doğum günündeki yaş\' olarak tam yıl kaydediliyor. Bu durumda 20–29 yaş sınıfının gerçek sınırları hangisidir?', '20 ve 30', ['19,5 ve 29,5', '20 ve 29', '19 ve 29'], '29 yaşında kaydedilen biri 29,99 yaşında olabilir ama 20 yaş altındaki biri bu sınıfa girmez; bu yüzden sınıf 20 ≤ yaş < 30 aralığını kapsar.'),
  ('Bir frekans tablosunda modal sınıftan önceki sınıfın frekansı, sonraki sınıfın frekansından büyüktür. Formülle bulunan mod modal sınıfın neresinde yer alır?', 'Orta noktanın alt sınıra yakın tarafında', ['Tam orta noktasında', 'Orta noktanın üst sınıra yakın tarafında', 'Modal sınıfın dışında, önceki sınıfın içinde'], 'Önceki frekans büyükse d₁ küçük, d₂ büyük olur; d₁/(d₁ + d₂) < 1/2 olduğundan mod alt sınıra daha yakındır.'),
  ('50 öğrencinin puanları gruplanmıştır: 40–50: 6, 50–60: 14, 60–70: 18, 70–80: 12. Q₃ = L + (3n/4 − F)/f·h formülüyle üçüncü çeyrek yaklaşık kaçtır?', '69,7', ['70,0', '67,5', '72,25'], '3n/4 = 37,5. Birikimli frekanslar 6, 20, 38 olduğundan Q₃ 60–70 sınıfındadır: 60 + (37,5 − 20)/18·10 ≈ 69,7.'),
  ('Sınıf orta noktalarıyla hesaplanan varyansın genellikle gerçek varyanstan biraz büyük çıkmasının nedeni ve bunun için önerilen düzeltme hangisidir?', 'Gruplama hatası; Sheppard düzeltmesi', ['Örneklem hatası; n − 1 düzeltmesi', 'Yuvarlama hatası; Bessel düzeltmesi', 'Aykırı değerler; winsorize düzeltmesi'], 'Gözlemleri orta noktaya toplamak, sürekli ve düzgün yoğunluklu verilerde yaklaşık h²/12 kadar fazladan varyans ekler; Sheppard düzeltmesi bunu çıkarır.'),
  ('50 kişinin girdiği, eşit puan bulunmayan bir sınavda birinci olan öğrencinin yüzdelik sırası, (B + 0,5·E)/N × 100 formülüyle kaçtır?', '99', ['100', '98', '50'], 'B = 49, E = 1 olduğundan (49 + 0,5)/50 × 100 = 99 bulunur; bu formülle 100 değerine ulaşılmaz.'),
  ('Beş pozitif tam sayının ortalaması 10, medyanı 12\'dir (sayılar tekrar edebilir). Bu sayıların en büyüğü en çok kaç olabilir?', '24', ['26', '22', '37,5'], 'Toplam 50\'dir. Sıralı a ≤ b ≤ 12 ≤ d ≤ e\'de e\'yi büyütmek için a = b = 1 ve d = 12 alınır: e = 50 − 1 − 1 − 12 − 12 = 24.'),
  ('Birbirinden farklı beş pozitif tam sayının medyanı 8\'dir. Bu sayıların ortalaması en az kaç olabilir?', '6', ['5', '6,4', '8'], 'En küçük seçim 1, 2, 8, 9, 10\'dur; toplam 30, ortalama 6\'dır.'),
  ('Negatif olmayan on sayının ortalaması 20\'dir. Bu sayılardan en fazla kaçı 50\'den büyük olabilir?', '3', ['4', '2', '1'], 'Toplam 200\'dür. Dört sayı 50\'den büyük olsa toplamları 200\'ü aşardı; üç sayı ise (ör. 60, 60, 60 ve kalanlar 20 toplamlı) mümkündür.'),
  ('0–100 arası puanlanan bir sınavda dokuz öğrencinin ortalaması 40\'tır. Medyan puan en çok kaç olabilir?', '72', ['40', '80', '100'], 'Medyan 5. puandır. İlk dört puan 0, son beş puan medyana eşit m alınırsa 5m = 360 olur; m = 72.'),
  ('Beş tam sayının tek modu 3, medyanı 5 ve ortalaması 6\'dır. En büyük sayı en çok kaç olabilir?', '13', ['14', '12', '11'], 'Sayılar 3, 3, 5, d, e biçimindedir ve d + e = 19 olmalıdır. Mod tek kalsın diye d > 5 ve d ≠ e gerekir; d = 6 alınınca e = 13 olur.'),
  ('Beş sayının modu 4, medyanı 6, açıklığı 10 ve tek modludur. Sayılar küçükten büyüğe a, b, c, d, e ise a + b + c + e toplamı kaçtır?', '28', ['26', '24', '30'], 'Tek mod 4 ve medyan 6 olduğundan a = b = 4, c = 6\'dır. Açıklık 10 olduğundan e = 14; a + b + c + e = 4 + 4 + 6 + 14 = 28.'),
  ('Yedi sayının medyanı 12\'dir. Bu sayılardan medyandan küçük olan biri 20\'ye yükseltilirse yeni medyan için hangisi kesindir?', '12\'den küçük olamaz', ['12 olarak kalır', 'Kesin olarak 20 olur', 'Kesin olarak artar'], 'Medyanın altındaki bir sayı üste geçince medyan 12 ya da 12 ile bir sonraki sayı arasında bir değere kayar; azalamaz ama eşit de kalabilir (ör. dördüncü ve beşinci sayılar 12 ise).'),
  ('Ortalamayı her yeni gözlemde baştan hesaplamadan güncellemek için kullanılan formül hangisidir? (x̄ₙ: n gözlemli ortalama)', 'x̄ₙ = x̄ₙ₋₁ + (xₙ − x̄ₙ₋₁)/n', ['x̄ₙ = x̄ₙ₋₁ + xₙ/n', 'x̄ₙ = (x̄ₙ₋₁ + xₙ)/2', 'x̄ₙ = x̄ₙ₋₁ · n/(n − 1) + xₙ/n'], 'Yeni ortalama, eski ortalamaya yeni gözlemin ondan farkının 1/n\'i eklenerek bulunur; (n − 1)x̄ₙ₋₁ + xₙ toplamının n\'ye bölünmesiyle aynıdır.'),
  ('Bilgisayarda varyansı Σx² − n·x̄² formülüyle hesaplamak, değerleri çok büyük ama birbirine çok yakın verilerde (ör. 1 000 000,1; 1 000 000,2; …) neden sorun çıkarabilir?', 'Çok yakın iki büyük sayı çıkarılırken basamak kaybı olur', ['Formül yalnız tam sayılar için geçerli olduğundan', 'Σx² her zaman negatif çıkacağından', 'Bu formül anakütle değil yalnız örneklem varyansını verdiğinden'], 'Σx² ve n·x̄² neredeyse eşit, çok büyük sayılardır; çıkarma işleminde yuvarlama hataları sonucu bozar. Önce ortalamayı çıkarmak ya da ardışık (Welford tipi) yöntemler kullanmak daha güvenlidir.'),
  ('Varyansı tek geçişte, sayısal olarak kararlı biçimde ve her yeni gözlemle güncelleyerek hesaplayan, 1962\'de yayımlanan yöntem kimin adıyla anılır?', 'B. P. Welford', ['Karl Pearson', 'William Gosset', 'Jerzy Neyman'], 'Welford\'un 1962 tarihli yöntemi ortalamayı ve kare sapmalar toplamını her gözlemde güncelleyerek büyük sayıların farkından doğan hatayı azaltır.'),
  ('İki gözlemden oluşan bir örneklemin değerleri 12 ve 20\'dir. Örneklem standart sapması (n − 1 ile) kaçtır?', '4√2', ['4', '8√2', '2√2'], 'Örneklem varyansı (a − b)²/2 = 64/2 = 32\'dir; standart sapma √32 = 4√2 ≈ 5,66.'),
  ('Bir dolum makinesinde hedef 500 g\'dır. Dolumların ortalaması 502 g, anakütle standart sapması 3 g\'dır. Dolumların hedeften farklarının karelerinin ortalaması kaç g²\'dir?', '13', ['9', '5', '10,5'], 'Hedef etrafındaki ortalama kare fark = varyans + (ortalama − hedef)² = 9 + 2² = 13\'tür.'),
  ('Samuelson eşitsizliğine göre n gözlemli bir verideki her gözlem ortalamadan en çok √(n − 1)·σ uzaklıktadır (σ: anakütle standart sapması). 10 gözlemli, σ = 2 olan bir veride bir gözlem ortalamadan en çok kaç birim uzak olabilir?', '6', ['4', '2√10', '20'], '√(10 − 1)·2 = 3·2 = 6 birimdir; daha uzak bir gözlem varyansı 4\'ün üstüne çıkarırdı.'),
  ('Her veri için ortalama ile medyan arasındaki uzaklığın anakütle standart sapmasını aşamayacağı bilinmektedir. Ortalaması 50 ve standart sapması 4 olan bir verinin medyanı aşağıdakilerden hangisi olamaz?', '55', ['47', '53', '50,5'], '|ortalama − medyan| ≤ σ olduğundan medyan 46 ile 54 arasında olmalıdır; 55 bu aralığın dışındadır.'),
  ('−3, −1, 2 verisinin her değerinin karesi alınıyor. Yeni verinin medyanı kaçtır?', '4', ['1', '9', '14/3'], 'Kareler 9, 1, 4\'tür; sıralanınca 1, 4, 9 ve medyan 4 olur. Kare alma negatif değerlerde sıralamayı bozduğundan eski medyanın karesi (1) çıkmaz.'),
  ('Bir veride her değer y = −x dönüşümüyle işaret değiştiriyor. y verisinin 90. yüzdeliği x verisinin hangi ölçüsüne eşittir?', '−P₁₀ değerine', ['−P₉₀ değerine', 'P₉₀ değerinin kendisine', '−P₅₀ değerine'], 'Azalan bir dönüşüm sıralamayı tersine çevirir: x\'te en küçük %10\'luk dilim, y\'de en büyük %10\'luk dilim olur. Bu yüzden y\'nin P₉₀\'ı −P₁₀(x)\'tir.'),
  ('Aynı günlerin sıcaklıkları Celsius ve Fahrenheit cinsinden ayrı ayrı özetlendiğinde değişim katsayıları farklı çıkıyor. Bunun nedeni nedir?', 'Aralık ölçeğinde sıfır keyfî olduğundan DK anlamsızdır', ['Fahrenheit ölçeği daha duyarlı olduğu için', 'Celsius\'ta varyans tanımsız olduğu için', 'İki ölçekte gün sayıları farklı olduğu için'], 'F = 1,8C + 32 dönüşümündeki 32 eklenmesi ortalamayı değiştirir ama standart sapmayı değiştirmez; oran bozulur. DK yalnız gerçek sıfırı olan oran ölçeğinde anlamlıdır.'),
  ('40 öğrencinin puanları için \'-den az\' birikimli frekanslar şöyledir: 40\'tan az 6, 50\'den az 16, 60\'tan az 32, 70\'ten az 40. İnterpolasyonla medyan kaçtır?', '52,5', ['50', '55', '53,75'], 'n/2 = 20. Medyan 50–60 sınıfındadır (öncesi 16, sınıf frekansı 32 − 16 = 16): 50 + (20 − 16)/16·10 = 52,5.'),
  ('50 gözlemli gruplanmış bir dağılımda 60–70 sınıfının frekansı 10, bu sınıftan önceki birikimli frekans 22\'dir. 65 değerinin interpolasyonla yüzdelik sırası kaçtır?', '54', ['44', '64', '49,5'], '65, sınıfın tam ortasıdır; altında yaklaşık 22 + 5 = 27 gözlem kalır. 27/50 = 0,54, yani yüzdelik sıra 54\'tür.'),
  ('1, 2, 3, 4, 5 değerlerinin frekansları sırasıyla 2, 3, 5, 6, 4\'tür. Çeyrekler, medyan dışarıda bırakılarak alt ve üst 10\'ar gözlemin medyanı olarak alınırsa Q₁ kaçtır?', '2,5', ['2', '3', '2,75'], 'Alt yarı 1, 1, 2, 2, 2, 3, 3, 3, 3, 3\'tür; 5. ve 6. değerler 2 ve 3 olduğundan Q₁ = 2,5.'),
  ('Normal dağılıma yakın verilerde medyan mutlak sapma (MAD) yaklaşık 1,4826 ile çarpılarak standart sapmanın dirençli bir tahmini elde edilir. MAD\'ı 4 olan bir veri için bu tahmin yaklaşık kaçtır?', '5,93', ['2,70', '4,00', '11,86'], '1,4826 × 4 ≈ 5,93\'tür. Çarpan, normal dağılımda MAD ≈ 0,6745σ olmasından gelir.'),
  ('Değiştirilmiş z-puanı Mᵢ = 0,6745·(xᵢ − medyan)/MAD ile hesaplanır ve |Mᵢ| > 3,5 olan gözlemler aykırı sayılır. Medyanı 50, MAD\'ı 4 olan bir veride 72 değeri için hangisi doğrudur?', 'Mᵢ ≈ 3,71 olduğundan aykırıdır', ['Mᵢ = 5,5 olduğundan aykırıdır', 'Mᵢ ≈ 2,45 olduğundan aykırı değildir', 'Mᵢ ≈ 3,30 olduğundan aykırı değildir'], '0,6745·22/4 ≈ 3,71 > 3,5 olduğundan 72 aykırı kabul edilir.'),
  ('Aykırı değer avında \'ortalamadan 3 standart sapmadan uzak\' ölçütü kullanılıyor. Aynı tarafta iki büyük aykırı değer bulunan küçük bir veride bu ölçütün aykırıları yakalayamamasına ne ad verilir?', 'Maskeleme', ['Kırpma', 'Yumuşatma', 'Sızıntı etkisi'], 'Aykırı değerler ortalamayı kendilerine doğru çeker ve standart sapmayı şişirir; bu yüzden z-puanları küçük kalır ve birbirlerini gizlerler.'),
  ('5 gözlemli bir veride z-puanları anakütle standart sapmasıyla hesaplanıyor. Bu veride herhangi bir gözlemin |z| değeri en çok kaç olabilir?', '2', ['3', '5', '√5'], 'Samuelson eşitsizliğine göre |z| ≤ √(n − 1) = √4 = 2\'dir. Bu yüzden küçük veride \'|z| > 3\' kuralı hiçbir aykırıyı yakalayamaz.'),
  ('1\'den 9\'a kadar tam sayılardan oluşan veride Tukey menteşeleri, medyan her iki yarıya da katılarak hesaplanır. Alt menteşe kaçtır?', '3', ['2,5', '2', '3,5'], 'Medyan 5 alt yarıya katılınca alt yarı 1, 2, 3, 4, 5 olur ve medyanı 3\'tür. Medyan dışarıda bırakılsaydı 2,5 bulunurdu.'),
  ('Aritmetik ortalamanın kırılma noktası neden %0 kabul edilir?', 'Tek bir uç gözlem ortalamayı sınırsız kaydırabilir', ['Ortalama hiçbir aykırı değerden etkilenmez', 'Ortalama yalnız pozitif verilerde tanımlıdır', 'Ortalama sıralama gerektirmez'], 'Tek bir gözlem bile yeterince büyütülürse ortalama istenen her değere çekilebilir; n büyüdükçe bunun oranı 1/n → 0 olur.'),
  ('Aynı veri için NumPy\'nin np.std(x) ve pandas\'ın x.std() komutları farklı sonuç veriyor. Bunun nedeni nedir?', 'Biri varsayılan olarak n\'ye, öteki n − 1\'e bölüyor', ['pandas eksik değerleri sıfır kabul ediyor', 'NumPy veriyi önce sıralıyor', 'pandas standart sapma yerine varyans veriyor'], 'NumPy\'de varsayılan ddof = 0, pandas\'ta ddof = 1\'dir; aynı veride pandas\'ın sonucu biraz daha büyük çıkar.'),
  ('Python\'daki pandas kütüphanesinin sayısal bir sütun için describe() komutu varsayılan olarak aşağıdakilerden hangisini raporlamaz?', 'Mod', ['Standart sapma', '%25\'lik değer', 'En küçük değer'], 'describe() sayısal sütunlar için sayım, ortalama, standart sapma, en küçük, %25, %50, %75 ve en büyük değeri verir; modu vermez.'),
  ('Merkezî eğilim ölçüsü olarak \'mod\' (mode) terimini 1895\'te istatistiğe kazandıran kimdir?', 'Karl Pearson', ['William Gosset', 'John Tukey', 'Pafnuti Çebişev'], 'Pearson, en sık görülen değeri adlandırmak için \'mode\' terimini 1895 tarihli çalışmasında önermiştir.'),
  ('Leptokurtik, platikurtik ve mezokurtik terimlerini 1905\'te ortaya koyarak dağılımların basıklığını adlandıran istatistikçi kimdir?', 'Karl Pearson', ['Francis Galton', 'Florence Nightingale', 'Ronald Fisher'], 'Pearson 1905\'teki çalışmasında \'kurtosis\' kavramını ve bu üç dağılım türünün adlarını tanıtmıştır.'),
  ('\'Yüzdelik\' (percentile) terimini 1885\'te kullanarak insan özelliklerinin ölçülmesinde yaygınlaştıran bilim insanı kimdir?', 'Francis Galton', ['Karl Pearson', 'Carl Friedrich Gauss', 'Adolphe Quetelet'], 'Galton, antropometri çalışmalarında bireyleri sıralayıp konumlarını yüzdelik olarak ifade etmiştir.'),
  ('Çebişev eşitsizliği, onu Çebişev\'den önce (1853) yayımlayan Fransız matematikçinin adıyla birlikte de anılır. Bu matematikçi kimdir?', 'Irénée-Jules Bienaymé', ['Pierre-Simon Laplace', 'Siméon Denis Poisson', 'Abraham de Moivre'], 'Eşitsizlik bu nedenle \'Bienaymé-Çebişev eşitsizliği\' olarak da adlandırılır; Çebişev 1867\'de daha genel biçimini kanıtlamıştır.'),
  ('10 gözlemli bir verinin bütün değerleri anakütle standart sapması kullanılarak z-puanına çevriliyor. z-puanlarının kareleri toplamı kaçtır?', '10', ['1', '0', '√10'], 'z-puanlarının varyansı 1 ve ortalaması 0 olduğundan Σz²/n = 1\'dir; Σz² = n = 10 olur.'),
  ('n gözlemli bir veride z-puanları örneklem standart sapması (n − 1 bölücülü s) ile hesaplanırsa z-puanlarının kareleri toplamı neye eşit olur?', 'n − 1', ['n', '1', 'n·(n − 1)'], 'Σ(x − x̄)² = (n − 1)s² olduğundan Σz² = Σ(x − x̄)²/s² = n − 1 bulunur.'),
  ('Dört kategorili sınıflayıcı bir değişkende değişim oranı (1 − f_mod/n) en çok kaç olabilir?', '0,75', ['1', '0,25', '0,667'], 'Modal frekans en az n/4 olabilir (dört kategori eşit dağıldığında); bu durumda değişim oranı 1 − 1/4 = 0,75 olur.'),
  ('Nitel değişim indeksi IQV = K/(K − 1)·(1 − Σp²) formülüyle hesaplanır. Üç kategorinin oranları 0,5; 0,3; 0,2 ise IQV yaklaşık kaçtır?', '0,93', ['0,62', '0,38', '1,245'], 'Σp² = 0,25 + 0,09 + 0,04 = 0,38. IQV = 1,5·(1 − 0,38) = 1,5·0,62 = 0,93.'),
  ('1 − Σp² ile hesaplanan Gini-Simpson çeşitlilik ölçüsü olasılık diliyle nasıl yorumlanır?', 'İadeli seçilen iki gözlemin farklı kategoride olma olasılığı', ['Rastgele seçilen tek bir gözlemin modal kategoride bulunma olasılığı', 'Kategori sayısının gözlem sayısına oranı', 'En büyük ve en küçük kategori oranları arasındaki fark'], 'Σp², rastgele ve yerine koyarak seçilen iki gözlemin aynı kategoriden gelme olasılığıdır; 1\'den çıkarılınca farklı kategoriden gelme olasılığı elde edilir.'),
  ('A grubunun ortalaması 60, B grubununki 80\'dir. İki grup birleşince ortalama 72 oluyor. A ve B gruplarının kişi sayılarının oranı (nA : nB) kaçtır?', '2 : 3', ['3 : 2', '1 : 1', '3 : 5'], 'Birleşik ortalama gruplara olan uzaklıklarla ters orantılıdır: nA/nB = (80 − 72)/(72 − 60) = 8/12 = 2/3.'),
  ('Bir ülkenin illerinde \'tipik ilin\' hane gelirini değil, \'tipik hanenin\' gelirini bulmak isteyen bir araştırmacı il değerlerini birleştirirken hangi yaklaşımı seçmelidir?', 'Hane sayılarıyla ağırlıklandırarak', ['Her ile eşit ağırlık vererek', 'Yalnız en kalabalık ili kullanarak', 'İl medyanlarının basit ortalamasını alarak'], 'Her hanenin eşit sayılması için il değerleri hane sayısına göre ağırlıklandırılmalıdır; eşit ağırlık küçük illeri olduğundan fazla temsil eder.'),
  ('Dokuz gözlemli bir veriye bir değer eklenince ortalama 2 birim artıyor. Eklenen değer eski ortalamadan kaç birim büyüktür?', '20', ['2', '18', '22,5'], 'Eski ortalama m ise (9m + x)/10 = m + 2\'den x = m + 20 bulunur.'),
  ('12 gözlemli bir veride ortalamanın üstündeki değerlerin ortalamadan farklarının toplamı 18\'dir. Ortalamadan ortalama mutlak sapma kaçtır?', '3', ['1,5', '6', '2,25'], 'Ortalamadan sapmaların toplamı 0 olduğundan aşağıdaki sapmaların toplamı −18\'dir. Mutlak sapmalar toplamı 36, ortalaması 36/12 = 3.'),
  ('Bir verideki her değer iki kez yazılarak gözlem sayısı ikiye katlanıyor. Aşağıdakilerden hangisi değişir?', 'Örneklem varyansı (n − 1 ile)', ['Aritmetik ortalama', 'Medyan', 'Anakütle varyansı (n bölücülü)'], 'Kare sapmalar toplamı ikiye katlanır; n\'ye bölünen varyans aynı kalır ama n − 1\'e bölünen varyans 2SS/(2n − 1) olur ve küçülür.'),
  ('Ortalaması 10, medyanı 8 olan bir veride her x değeri y = 20 − x dönüşümüyle değiştiriliyor. Yeni verinin ortalaması ve medyanı nedir?', 'Ortalama 10, medyan 12', ['Ortalama 10, medyan 8', 'Ortalama −10, medyan −8', 'Ortalama 20, medyan 12'], 'Ortalama 20 − 10 = 10, medyan 20 − 8 = 12 olur. Dönüşüm veriyi ortalama etrafında yansıttığı için sağa çarpıklık sola çarpıklığa döner.'),
  ('Bir hastanede yatış süreleri \'ortalama 5 gün, standart sapma 8 gün\' olarak raporlanmıştır. Yatış süresi negatif olamayacağına göre dağılımın biçimi için en makul çıkarım hangisidir?', 'Belirgin biçimde sağa çarpıktır', ['Simetrik ve normale yakındır', 'Belirgin biçimde sola çarpıktır', 'Bütün değerler 5 güne çok yakındır'], 'Ortalamanın bir standart sapma altı negatife düşer; negatif değer olamayacağından birkaç çok uzun yatışın ortalamayı ve standart sapmayı büyüttüğü sağa çarpık bir dağılım söz konusudur.'),
  ('Bir rüzgâr gülünde iki ölçüm 350° ve 10° yön açısı vermiştir. Bu iki yönün ortalama yönü olarak hangisi anlamlıdır?', '0° (kuzey)', ['180° (güney)', '170°', '90° (doğu)'], 'Açılar döngüseldir: 350° ile 10° kuzeyin iki yanında 10\'ar derecedir. Sayıların aritmetik ortalaması (180°) tam ters yönü verir; yönler için döngüsel ortalama kullanılır.'),
  ('Sıralı bir ölçekte (\'kötü, orta, iyi, çok iyi\') 40 yanıtın tam 20\'si \'orta\', 20\'si \'iyi\' ise medyan için en doğru ifade hangisidir?', '\'Orta\' ile \'iyi\' arasında kalır', ['\'Orta\' ile \'iyi\'nin aritmetik ortalaması 2,5\'tir', '\'İyi\'dir, çünkü daha yüksek kategoridir', 'Medyan tanımsızdır, çünkü mod da iki tanedir'], '20. ve 21. yanıtlar farklı kategorilerdedir. Sayısal olmayan sıralı veride bu iki kategorinin ortalaması alınamaz; medyan iki kategori arasında kalır.'),
  ('Aşağıdaki verilerden hangisinde çeyrekler açıklığı 0 olduğu hâlde açıklık çok büyüktür? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '1, 5, 5, 5, 5, 5, 5, 100', ['5, 10, 15, 20, 25, 30, 35, 40', '1, 1, 1, 1, 100, 100, 100, 100', '40, 45, 50, 55, 60, 65, 70, 75'], 'İlk veride alt yarı 1, 5, 5, 5 ve üst yarı 5, 5, 5, 100\'dür; Q₁ = Q₃ = 5 ve IQR = 0, ama açıklık 99\'dur.'),
  ('Bir verinin standart sapması sıfırdan büyük olduğu hâlde medyan mutlak sapması (MAD) 0 çıkmıştır. Bu durum ne gösterir?', 'Gözlemlerin yarısından fazlası medyana eşittir', ['Bütün gözlemler birbirine ve ortalamaya eşittir', 'Veride hiç aykırı değer yoktur', 'Ortalama medyandan büyüktür'], 'MAD, medyandan mutlak sapmaların medyanıdır. Gözlemlerin yarıdan fazlası medyana eşitse bu sapmaların medyanı 0 olur; diğer gözlemler farklı olabilir.'),
  ('Örneklem varyansında n − 1 bölücüsünün \'serbestlik derecesi\' olarak yorumlanmasının nedeni nedir?', 'Sapmalar toplamı 0 olduğundan biri ötekilerce belirlenir', ['Her örneklemde bir gözlem mutlaka aykırı olduğundan', 'En küçük değer hesaba katılmadığından', 'Örneklemdeki son gözlem her zaman ortalamaya eşit olduğundan'], 'İlk n − 1 sapma bilinince sonuncusu sapmaların toplamının 0 olması koşuluyla belirlenir; bu yüzden bağımsız bilgi n − 1 tanedir.'),
  ('Hodges-Lehmann konum tahmini, verideki bütün (xᵢ + xⱼ)/2 ortalamalarının (i ≤ j) medyanıdır. 1, 2, 9 verisi için bu tahmin kaçtır?', '3,5', ['2', '4', '5,25'], 'Ortalamalar 1, 2, 9, 1,5, 5 ve 5,5\'tir. Sıralanınca 1; 1,5; 2; 5; 5,5; 9 olur ve medyan (2 + 5)/2 = 3,5\'tir.'),
  ('Ortalamadan ortalama mutlak sapma, anakütle standart sapmasına hangi durumda eşit olur?', 'Tüm gözlemler ortalamaya eşit uzaklıktayken', ['Veri sağa çarpık olduğunda', 'Gözlem sayısı tek olduğunda', 'Ortalama ile medyan birbirinden farklı olduğunda'], 'Mutlak sapmaların ortalaması, kare sapmaların ortalamasının karekökünden küçük ya da ona eşittir; eşitlik yalnız bütün |xᵢ − x̄| değerleri aynıyken sağlanır.'),
  ('Pozitif bir veri için kuvvet ortalaması Mₚ\'de p çok büyük değerlere götürülürse ortalama hangi değere yaklaşır?', 'Verinin en büyük değerine', ['Aritmetik ortalamaya', 'Medyana', 'Verinin en küçük gözlem değerine'], 'Büyük p\'de en büyük değerin kuvveti toplamı baskılar; Mₚ en büyük gözleme yaklaşır. p çok küçük (negatif) olunca en küçük değere yaklaşır.'),
  ('Bir okulda iki sınıf vardır: birinde 10, ötekinde 50 öğrenci okumaktadır. Okul \'ortalama sınıf mevcudumuz 30\' diyor. Öğrencilere \'sınıfınız kaç kişi?\' diye sorulup yanıtların ortalaması alınırsa sonuç yaklaşık kaç olur?', '43,3', ['30', '50', '26,7'], '10 öğrenci 10, 50 öğrenci 50 der: (10·10 + 50·50)/60 = 2600/60 ≈ 43,3. Kalabalık sınıflar öğrenci gözünden daha çok temsil edilir.'),
  ('A grubu 1, 2, 3; B grubu 4, 5, 6 değerlerinden oluşur. 4 değeri B\'den A\'ya taşınırsa iki grubun ortalamaları nasıl değişir?', 'İkisi de 0,5 artar', ['İkisi de 0,5 azalır', 'A\'nınki artar, B\'ninki azalır', 'İkisi de değişmez'], 'A: 1, 2, 3, 4 olur ve ortalama 2\'den 2,5\'e çıkar. B: 5, 6 olur ve ortalama 5\'ten 5,5\'e çıkar. Taşınan değer A\'nın ortalamasından büyük, B\'ninkinden küçük olduğu için ikisi de artar.'),
  ('1–3, 4–6 ve 7–11 tam sayılarından oluşan üç grubun medyanları sırasıyla 2, 5 ve 9\'dur. Bu üç medyanın medyanı ile 1\'den 11\'e kadar bütün sayıların medyanı arasındaki fark kaçtır?', '1', ['0', '2', '3,5'], 'Medyanların medyanı 5\'tir; birleşik 11 sayının medyanı 6\'dır. Grup medyanlarından birleşik medyan elde edilemez.'),
  ('−1, 0, 0, 1 verisinin basıklığı (m₄/m₂²) kaçtır?', '2', ['3', '1', '0,5'], 'Ortalama 0\'dır; m₂ = (1 + 0 + 0 + 1)/4 = 0,5 ve m₄ = 0,5\'tir. Basıklık 0,5/0,25 = 2 bulunur; 3\'ten küçük olduğu için platikurtiktir.'),
  ('Güncel istatistik literatüründe basıklığın (kurtosis) esas olarak neyi yansıttığı vurgulanır?', 'Kuyruk ağırlığını', ['Yalnız tepe noktasının sivriliğini', 'Dağılımın ortalamasının konumunu', 'Dağılımın sağa ya da sola eğikliğini'], 'Dördüncü moment büyük sapmalarla belirlenir; bu yüzden basıklık daha çok kuyruklardaki uç değerlerin yoğunluğunu ölçer. \'Sivrilik\' yorumu yanıltıcı olabilir.'),
  ('Bir verinin moment çarpıklık katsayısı tam 0 bulunmuştur. Buna göre aşağıdakilerden hangisi kesinlikle söylenebilir?', 'Üçüncü merkezî moment 0\'dır', ['Dağılım tam simetriktir', 'Ortalama medyana tam olarak eşittir', 'Veri normal dağılıma uyar'], 'Çarpıklık 0 demek pozitif ve negatif sapma küplerinin birbirini götürmesi demektir. Simetrik olmayan bazı dağılımlarda da bu olabilir; simetri ya da ortalama = medyan garanti edilmez.'),
  ('Bilgisayar başarım testlerinde, bir referans makineye göre normalize edilmiş hız oranlarını özetlemek için geometrik ortalama tercih edilir. Bunun temel nedeni nedir?', 'Sonucun referans seçimine bağlı olmaması', ['Geometrik ortalamanın her zaman en büyük ortalama olması', 'Oranların toplamının anlamlı olması', 'Hesap makinesinde daha kolay bulunması'], 'Oranların aritmetik ortalaması referans değişince sıralamayı değiştirebilir; geometrik ortalamada ise oranların oranı korunur ve sonuç referanstan bağımsızdır.'),
  ('Eşit hacimde pH 3 ve pH 5 olan iki çözelti karıştırılıyor. Karışımın pH değeri için hangisi doğrudur?', 'Yaklaşık 3,3\'tür', ['Tam 4\'tür, çünkü iki pH\'nin ortalamasıdır', 'Tam 5\'tir, çünkü zayıf asit baskındır', 'Tam 8\'dir, çünkü pH değerleri toplanır'], 'pH logaritmik bir ölçektir. Ortalanması gereken H⁺ derişimidir: (10⁻³ + 10⁻⁵)/2 ≈ 5,05·10⁻⁴; bunun pH\'si ≈ 3,3\'tür.'),
  ('0, 0, 0, 4 verisinin üçüncü merkezî momenti, (1/n)·Σ(xᵢ − x̄)³, kaçtır?', '6', ['0', '27', '1,5'], 'Ortalama 1\'dir; sapmalar −1, −1, −1, 3\'tür. Küplerin toplamı −3 + 27 = 24, ortalaması 24/4 = 6\'dır. Pozitif değer sağa çarpıklığı gösterir.'),
  ('Birbirinden farklı beş tam sayının açıklığı 6, ortalaması 10\'dur. En küçük sayı kaçtır?', '7', ['6', '8', '5,5'], 'En küçük a ise en büyük a + 6\'dır ve aradaki üç sayı a + 1 ile a + 5 arasından seçilir. Toplam 50 koşulu yalnız a = 7 için sağlanır (ör. 7, 9, 10, 11, 13).'),
  ('Medyanı 7 ve tek modu 9 olan beş pozitif tam sayının toplamı en az kaç olabilir?', '28', ['25', '35', '27'], 'Sıralı a, b, 7, d, e\'de tek mod 9 ise d = e = 9 ve a ile b farklı olmalıdır. En küçük seçim 1, 2, 7, 9, 9\'dur; toplam 28.'),
  ('Gruplanmış bir veride 0–10 sınıfının frekansı 5, 10–20 sınıfınınki f, 20–30 sınıfınınki 10\'dur. İnterpolasyonla bulunan medyan 17,5 ise f kaçtır?', '10', ['8', '12', '12,5'], 'n = 15 + f\'dir. Medyan 10–20 sınıfında: 10 + ((15 + f)/2 − 5)/f·10 = 17,5. Buradan (5 + f)/(2f) = 0,75 ve f = 10.'),
  ('n − 1 bölücülü örneklem varyansı s², anakütle varyansının yansız bir tahmincisidir. Bunun karekökü olan s için hangisi doğrudur?', 'Ortalamada σ\'yı az tahmin eder', ['σ\'nın da tam yansız tahmincisidir', 'σ\'yı ortalamada biraz büyük tahmin eder', 'σ ile ilgisi yoktur'], 'Karekök içbükey bir dönüşüm olduğundan E[s] < √E[s²] = σ olur; s hafifçe aşağı yanlıdır.'),
  ('Üç öğrencinin iki sınavdaki puanları (birinci, ikinci) biçiminde A: (1, 10), B: (2, 0), C: (3, 1)\'dir. Toplam puanların medyanı ile iki sınavın medyanlarının toplamı arasındaki fark kaçtır?', '1', ['0', '2', '3,5'], 'Medyanlar 2 ve 1\'dir, toplamları 3\'tür. Toplam puanlar 11, 2, 4 olup medyanı 4\'tür. Fark 1\'dir; ortalamadan farklı olarak medyan toplanabilir değildir.'),
  ('Gini ortalama farkı, bütün gözlem çiftleri arasındaki mutlak farkların ortalamasıdır. 1, 2, 3 verisi için (üç farklı çift) bu ölçü kaçtır?', '4/3', ['1', '2', '0,67'], 'Çiftler (1, 2), (1, 3), (2, 3) olup mutlak farklar 1, 2, 1\'dir; ortalamaları 4/3\'tür.'),
  ('Emlak vergisi değerlendirmelerinde kullanılan dağılım katsayısı (COD), oranların medyandan ortalama mutlak sapmasının medyana bölünüp 100 ile çarpılmasıyla bulunur. Oranlar 0,9; 1,0; 1,1; 1,2; 0,8 ise COD kaçtır?', '12', ['10', '20', '15,8'], 'Medyan 1,0\'dır. Mutlak sapmalar 0,1; 0; 0,1; 0,2; 0,2; ortalamaları 0,12\'dir. COD = 0,12/1,0 × 100 = 12.'),
  ('Birbirinden çok farklı iki veri grubunun ortalamaları eşit, standart sapmaları da eşittir. Bu bilgiye göre iki grup hakkında hangisi kesinlikle söylenebilir?', 'Kareler ortalamaları eşittir', ['Medyanları eşittir', 'Açıklıkları birbirine eşittir', 'Modları eşittir'], 'Karelerin ortalaması x̄² + σ² olduğundan ortalaması ve standart sapması eşit gruplarda bu değer de eşittir. Medyan, açıklık ve mod farklı olabilir.'),
  ('Kanser çalışmalarında hayatta kalma süresi çoğunlukla ortalama yerine \'ortanca (medyan) sağkalım\' ile raporlanır. Bunun başlıca nedeni nedir?', 'Süreler çarpıktır ve bazıları henüz tamamlanmamıştır', ['Ortalama sağkalım süresi her zaman sıfırdır', 'Medyan hesaplamak için hasta sayısı gerekmez', 'Sağkalım süreleri sınıflayıcı bir değişkendir'], 'Birkaç uzun süre ortalamayı şişirir; ayrıca hayatta olan hastaların süreleri tamamlanmamıştır. Medyan, hastaların yarısının yaşadığı süre olarak bu koşullarda daha sağlam bir özettir.'),
  ('Aşağıdaki verilerden hangisinde aritmetik ortalama üçüncü çeyrekten bile büyüktür? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '1, 1, 1, 1, 1, 1, 1, 100', ['1, 2, 3, 4, 5, 6, 7, 8', '10, 20, 30, 40, 50, 60, 70, 80', '1, 100, 100, 100, 100, 100, 100, 100'], 'İlk veride Q₃ = 1 iken ortalama 107/8 ≈ 13,4\'tür. Çok uç tek bir değer ortalamayı verinin büyük bölümünün üstüne taşıyabilir.'),
  ('|ortalama − medyan| ≤ σ eşitsizliği göz önüne alınırsa Pearson\'un ikinci çarpıklık katsayısı 3(ortalama − medyan)/σ hangi aralıkta kalır?', '−3 ile +3 arasında', ['−1 ile +1 arasında', '0 ile 3 arasında', 'Sınırsızdır, her değeri alabilir'], '(ortalama − medyan)/σ en çok 1 olabildiğinden 3 ile çarpılınca katsayı −3 ile +3 arasında kalır.'),
  ('Değişim katsayısını (standart sapmanın ortalamaya oranı) 1896\'da göreli değişkenliği karşılaştırmak için tanıtan istatistikçi kimdir?', 'Karl Pearson', ['Ronald Fisher', 'Francis Galton', 'John Tukey'], 'Pearson, kalıtım üzerine 1896 tarihli çalışmasında farklı ölçekteki özelliklerin değişkenliğini karşılaştırmak için bu katsayıyı önermiştir.'),
  ('Zekâ testlerinde yaşa dayalı \'oran IQ\'su yerine aynı yaş grubunun ortalaması ve standart sapmasına dayanan \'sapma IQ\'su kullanımını 1939\'da başlatan psikolog kimdir?', 'David Wechsler', ['Alfred Binet', 'Lewis Terman', 'Charles Spearman'], 'Wechsler-Bellevue ölçeği (1939), puanları yaş grubunun ortalaması 100 ve standart sapması 15 olacak biçimde standartlaştırmıştır.'),
  ('30 gözlemli bir verinin ortalaması 50, anakütle varyansı 100\'dür. Ortalaması 40, varyansı 25 olan 10 gözlemlik bir alt grup veriden çıkarılırsa kalan 20 gözlemin anakütle varyansı kaç olur?', '62,5', ['75', '100', '118,75'], 'Kalan ortalama (1500 − 400)/20 = 55. Σx² toplamda 30·2600 = 78 000, alt grupta 10·1625 = 16 250; kalan 61 750/20 − 55² = 3087,5 − 3025 = 62,5.'),
  ('Ortalaması 10, anakütle varyansı 5 olan 4 gözlemli bir veriye 15 değeri ekleniyor. Yeni anakütle varyansı kaçtır?', '8', ['5', '9', '6,8'], 'Yeni ortalama (40 + 15)/5 = 11. Σx² = 4·(5 + 100) + 225 = 645; varyans 645/5 − 121 = 8.'),
  ('Varyans, ortalamaya hiç başvurmadan da tanımlanabilir. Aşağıdakilerden hangisi anakütle varyansına eşittir?', 'Bütün sıralı gözlem çiftleri arasındaki kare farkların ortalamasının yarısı', ['Gözlem çiftleri arasındaki mutlak farkların ortalaması', 'En büyük ve en küçük değerin farkının karesi', 'Ardışık gözlemler arasındaki farkların toplamı'], 'σ² = (1/(2n²))·ΣᵢΣⱼ(xᵢ − xⱼ)² özdeşliği geçerlidir; ör. 1, 2, 3 için kare farkların ortalaması 12/9, yarısı 2/3\'tür ve anakütle varyansına eşittir.'),
  ('Dow Jones Sanayi Ortalaması gibi bazı borsa göstergeleri hisseleri nasıl ağırlıklandırır?', 'Hisse fiyatlarına göre', ['Şirket çalışan sayısına göre', 'Bütün hisselere eşit ağırlıkla', 'İşlem hacminin karesine göre'], 'Dow Jones fiyat ağırlıklı bir göstergedir; fiyatı yüksek hisse, şirketin büyüklüğünden bağımsız olarak daha çok etki eder.'),
  ('Bir verinin ham momentleri m′₁ = 2, m′₂ = 5 ve m′₃ = 14\'tür. Üçüncü merkezî moment m₃ = m′₃ − 3m′₁m′₂ + 2(m′₁)³ formülüyle kaçtır?', '0', ['14', '−2', '6'], 'm₃ = 14 − 3·2·5 + 2·8 = 14 − 30 + 16 = 0; bu momentlere sahip veri çarpıklık göstermez.'),
  ('Kelley\'nin yüzdeliklere dayalı basıklık ölçüsü κ = Q/(P₉₀ − P₁₀) biçimindedir (Q: çeyrek sapma). Q₁ = 40, Q₃ = 60, P₁₀ = 25, P₉₀ = 75 olan bir veri için κ kaçtır?', '0,2', ['0,4', '0,25', '10'], 'Q = (60 − 40)/2 = 10; P₉₀ − P₁₀ = 50. κ = 10/50 = 0,2. Normal dağılımda bu değer yaklaşık 0,263\'tür.'),
  ('Bir tahminde tam isabet ödüllendiriliyor, yanlış tahmin ne kadar uzak olursa olsun aynı cezayı alıyor. Verideki değerlerden birini doğru tahmin etme şansını en yükseğe çıkaran tek tahmin hangisidir?', 'Mod', ['Aritmetik ortalama', 'Medyan', 'Orta değer'], 'Yalnız tam isabet önemliyse en sık görülen değeri söylemek en çok isabeti sağlar. Kare hatayı ortalama, mutlak hatayı medyan en küçük yapar.'),
  ('Bir c değeri seçilecek ve en kötü durumdaki hata, yani en büyük |xᵢ − c| en küçük yapılmak isteniyor. Hangi değer seçilmelidir?', 'Orta değer ((en küçük + en büyük)/2)', ['Aritmetik ortalama', 'Medyan', 'Mod'], 'En büyük sapma iki uçtan birine olan uzaklıktır; c iki ucun tam ortasında olduğunda bu uzaklık en küçük olur ve yarım açıklığa eşittir.'),
  ('2, 4, 6, 8 verisi için Σ|xᵢ − c| toplamını en küçük yapan c değerleri hangileridir?', '4 ile 6 arasındaki (uçlar dâhil) her değer', ['Yalnız 5', 'Yalnız 4', 'Yalnız 6'], 'Çift sayıda gözlemde ortadaki iki değer arasındaki her c için toplam aynıdır (8). Medyan olarak 5\'in seçilmesi bir uzlaşmadır.'),
  ('İki grup birleştirildiğinde birleşik varyans hangi iki bileşenin toplamı olarak yazılabilir?', 'Grup içi varyansların ağırlıklı ortalaması ile grup ortalamalarının birleşik ortalama etrafındaki varyansı', ['Grup varyanslarının toplamı ile grup büyüklüklerinin toplamı', 'Grup ortalamalarının toplamı ile grup varyanslarının çarpımı', 'En büyük grup varyansı ile en küçük grup varyansı'], 'Toplam değişkenlik, grupların kendi içindeki yayılımı ile grupların birbirinden uzaklığından (gruplar arası değişkenlik) oluşur.'),
  ('Bir değişken, gerçek değere eklenen ve ondan bağımsız rastgele ölçme hatası içeren bir araçla ölçülüyor. Gözlenen değerlerin varyansı gerçek değerlerin varyansına göre nasıldır?', 'Daha büyüktür; ölçme hatasının varyansı kadar eklenir', ['Daha küçüktür', 'Tam olarak eşittir', 'Ölçme hatası varyansın yarısını götürür'], 'Bağımsız hata eklendiğinde σ²gözlenen = σ²gerçek + σ²hata olur; ölçme hatası yayılımı şişirir.'),
  ('Bir verinin bütün değerleri −1 ile çarpılırsa çarpıklık ve basıklık nasıl değişir?', 'Çarpıklık işaret değiştirir, basıklık değişmez', ['İkisi de işaret değiştirir', 'İkisi de değişmez', 'Çarpıklık değişmez, basıklık işaret değiştirir'], 'Üçüncü moment tek kuvvet olduğundan işaret değiştirir; dördüncü moment çift kuvvet olduğundan aynı kalır.'),
  ('Trafik mühendisliğinde bir yolun hız sınırı belirlenirken serbest akan araçların hızlarının hangi yüzdeliği yaygın olarak ölçüt alınır?', '85. yüzdelik', ['50. yüzdelik', '10. yüzdelik', '99. yüzdelik'], '85. yüzdelik hız, sürücülerin büyük çoğunluğunun makul bulduğu hızı yansıttığı için hız sınırı çalışmalarında yaygın bir başvuru değeridir.'),
  ('Çevresel gürültü ölçümlerinde L₁₀, ölçüm süresinin %10\'unda aşılan ses düzeyidir. L₁₀ ses düzeylerinin hangi yüzdeliğine karşılık gelir?', '90. yüzdeliğine', ['10. yüzdeliğine', '50. yüzdeliğine', 'Ortalamasına'], 'Sürenin %10\'unda aşılan düzey, sürenin %90\'ında aşılmayan düzeydir; bu 90. yüzdeliktir.'),
  ('Python\'daki NumPy kütüphanesinin np.percentile işlevi varsayılan olarak yüzdelikleri hangi yöntemle hesaplar?', 'Konumu 1 + (n − 1)·p alan doğrusal interpolasyonla', ['En yakın sıradaki değeri alarak', 'Konumu (n + 1)·p alıp yukarı yuvarlayarak', 'Gruplanmış veri formülüyle'], 'NumPy\'nin varsayılan yöntemi \'linear\'dir; R\'nin varsayılan 7. türü ve Excel\'in PERCENTILE.INC işleviyle aynı sonucu verir.'),
  ('4 gözlemli bir verinin ortalaması 10, anakütle varyansı 5\'tir. Veriye eklenince anakütle varyansını değiştirmeyen ve ortalamadan büyük olan değer kaçtır?', '12,5', ['10', '15', '11,25'], 'Eklenen x için varyansın sabit kalması (x − 10)² = σ²·(n + 1)/n = 5·5/4 = 6,25 koşulunu gerektirir; x = 12,5 (ya da 7,5).'),
  ('Bir veride IQR/σ oranı yaklaşık 0,5 bulunmuştur (normal dağılımda bu oran yaklaşık 1,35\'tir). Bu durum en çok neye işaret eder?', 'Kuyrukların ağır olduğuna ya da uç değerlerin standart sapmayı şişirdiğine', ['Verinin tam normal dağıldığına', 'Bütün değerlerin eşit olduğuna', 'Verinin iki değerden oluştuğuna'], 'Ortadaki %50 dar (küçük IQR) ama standart sapma büyükse, yayılımın büyük kısmı uçlardaki birkaç değerden gelmektedir.'),
  ('Evet = 1, hayır = 0 kodlanmış bir değişkende \'evet\' oranı 0,9\'dur. Bu değişkenin anakütle standart sapmasının ortalamaya oranı (değişim katsayısı) yaklaşık kaçtır?', '0,33', ['0,111', '0,9', '3'], 'Ortalama p = 0,9, standart sapma √(0,9·0,1) = 0,3\'tür. DK = 0,3/0,9 ≈ 0,33.'),
  ('Bir veri setindeki bütün pozitif x değerlerinin aritmetik ortalaması 5 bulunmuştur. Şimdi her gözlemin yerine 1/x yazılıyor. Bu yeni değerlerin harmonik ortalaması kaçtır?', '1/5', ['5', '1/25', 'Belirlenemez'], '1/x değerlerinin harmonik ortalaması n/Σx\'tir; bu da 1/(aritmetik ortalama) = 1/5\'e eşittir.'),
  ('Sıralı (ordinal) ölçekteki bir değişken için çeyrekler açıklığının sayısal bir fark olarak hesaplanması neden sorunludur?', 'Kategoriler arasındaki uzaklıklar eşit ya da anlamlı sayılar değildir', ['Sıralı veride çeyrekler hiç belirlenemez', 'Sıralı veride medyan her zaman tanımsızdır', 'Sıralı veride en az 100 gözlem gerekir'], 'Çeyrek kategorileri (ör. Q₁ \'orta\', Q₃ \'iyi\') belirlenebilir; ama \'iyi − orta\' farkının sayısal bir anlamı yoktur, çünkü kodlar yalnız sıra bilgisi taşır.'),
  ('Geometrik ortalama neden Celsius cinsinden sıcaklıklar gibi aralık ölçekli veriler için uygun değildir?', 'Sıfır noktası keyfî olduğundan değerler sıfır ya da negatif olabilir ve oranlar anlamsızdır', ['Celsius ölçeğinde toplama yapılamadığından', 'Aralık ölçekli veride ortalama hiç tanımlı olmadığından', 'Geometrik ortalama yalnız sınıflayıcı veride kullanıldığından'], 'Geometrik ortalama oranlara dayanır ve pozitif değerler gerektirir; bu ancak gerçek sıfırı olan oran ölçeğinde anlamlıdır.'),
  ('Puanları 0 ile 100 arasında olan bir sınavda ortalama 98\'dir. Bhatia-Davis eşitsizliğine göre σ² ≤ (en büyük − ortalama)(ortalama − en küçük) olduğundan anakütle standart sapması en çok kaç olabilir?', '14', ['2', '9,9', '10'], 'σ² ≤ (100 − 98)(98 − 0) = 196 olduğundan σ ≤ 14\'tür. Ortalama bir uca çok yakınsa yayılım sınırlıdır.'),
  ('Çok büyük ve sürekli akan bir veride ortalamayı hesaplamak medyanı hesaplamaktan neden çok daha kolaydır?', 'Ortalama için yalnız toplam ve sayı tutmak yeter; medyan sıralama ya da bütün veriyi saklamayı gerektirir', ['Medyan yalnız tek sayıda gözlemde tanımlı olduğundan', 'Ortalama aykırı değerlerden etkilenmediğinden', 'Medyanı hesaplamak için önce varyansı bulmak gerektiğinden'], 'Ortalama her yeni gözlemle sabit bellekte güncellenebilir; tam medyan ise verinin sıralı konumuna bağlıdır ve genellikle bütün gözlemleri saklamayı gerektirir.'),
  ('1, 2, 9 verisinde (medyan 2, ortalama 4) aşağıdaki değişikliklerden hangisi medyanı değiştirip ortalamayı aynı bırakır?', '2\'yi 3 yapıp 9\'u 8 yapmak', ['9\'u 12 yapmak', '1\'i 0 yapmak', 'Her değere 1 eklemek'], 'Yeni veri 1, 3, 8\'dir: toplam yine 12, ortalama 4\'tür; medyan ise 3 olmuştur.'),
  ('Yatırım getirilerinde geometrik ortalama yaklaşık olarak aritmetik ortalama eksi varyansın yarısıdır (G ≈ A − σ²/2). Yıllık getirilerinin aritmetik ortalaması %10, standart sapması %20 olan bir fonun yıllık geometrik ortalama getirisi yaklaşık yüzde kaçtır?', '%8', ['%10', '%0', '%6'], 'σ² = 0,2² = 0,04; yarısı 0,02\'dir. G ≈ 0,10 − 0,02 = 0,08, yani yaklaşık %8. Oynaklık bileşik getiriyi aşağı çeker.'),
  ('Sınıf frekansları sırasıyla 10, 2, 2, 4, 6, 6 olan altı sınıflı bir dağılımda (n = 30) modal sınıf ile medyanın bulunduğu sınıf için hangisi doğrudur?', 'Modal sınıf birinci, medyan dördüncü sınıftadır', ['İkisi de birinci sınıftır', 'İkisi de dördüncü sınıftır', 'Modal sınıf altıncı, medyan üçüncü sınıftadır'], 'En büyük frekans (10) birinci sınıftadır. Birikimli frekanslar 10, 12, 14, 18 olduğundan ortadaki 15. ve 16. gözlemler dördüncü sınıftadır. Modal sınıf ile medyan sınıfı farklı olabilir.'),
  ('İngilizcedeki \'average\' (ortalama) sözcüğünün kökeni hangi uygulamaya dayanır?', 'Deniz ticaretinde gemi ve yük hasarının taraflar arasında paylaştırılmasına', ['Antik Yunan\'da oylama sonuçlarının toplanmasına', 'Roma\'da vergi gelirlerinin sayılmasına', 'Orta Çağ\'da tahıl hasadının tartılmasına'], 'Sözcük, deniz sigortası ve ticaretinde \'avarya\' (hasar) ile ilgili payların eşit dağıtılması anlamından gelir; eşit paylaştırma fikri ortalamanın anlamıyla örtüşür.'),
  ('Bir verinin çeyrekleri eşit aralıklıdır (Q₂ − Q₁ = Q₃ − Q₂), ama verinin en üstünde çok uzak birkaç değer vardır. Bowley çarpıklık katsayısı ile moment çarpıklık katsayısı için hangisi en olasıdır?', 'Bowley katsayısı 0, moment çarpıklığı pozitif', ['İkisi de 0', 'İkisi de negatif', 'Bowley katsayısı pozitif, moment çarpıklığı 0'], 'Bowley yalnız çeyreklere bakar ve ortadaki %50 simetrik olduğu için 0 verir; moment çarpıklığı uç değerlerin küplerinden güçlü biçimde etkilenir ve pozitif çıkar.'),
  ('1, 2, 3, 4, 5, 6, 20 verisinin Bowley çarpıklık katsayısı (Q₃ + Q₁ − 2Q₂)/(Q₃ − Q₁) kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '0', ['0,5', '1', '−0,5'], 'Q₁ = 2, Q₂ = 4, Q₃ = 6 bulunur; (6 + 2 − 8)/4 = 0. Uçtaki 20 değeri çeyrekleri etkilemediği için Bowley ölçüsü bu çarpıklığı görmez.'),
  ('Normal dağılıma yakın verilerde ortalamadan ortalama mutlak sapma, standart sapmanın yaklaşık kaç katıdır?', '0,8', ['1,35', '0,67', '1'], 'Normal dağılımda OMS = σ·√(2/π) ≈ 0,8σ\'dır; bu yüzden OMS her zaman σ\'dan biraz küçük çıkar.'),
  ('Kalp atış hızı değişkenliği çalışmalarında kullanılan SDNN göstergesi neyi ifade eder?', 'Ardışık normal kalp atışları arasındaki sürelerin standart sapmasını', ['Dakikadaki ortalama atış sayısını', 'En yüksek ve en düşük nabzın farkını', 'Atış sürelerinin medyanını'], 'SDNN (standard deviation of NN intervals), normal atımlar arası sürelerin standart sapmasıdır; kalp ritmindeki değişkenliği özetler.'),
  ('Eğitim değerlendirmesinde kullanılan \'normal eğri eşdeğeri\' (NCE) puanlarının ortalaması ve standart sapması hangi değerlerdir?', 'Ortalama 50, standart sapma yaklaşık 21,06', ['Ortalama 50, standart sapma 10', 'Ortalama 100, standart sapma 15', 'Ortalama 5, standart sapma 2'], 'NCE ölçeği 1 ile 99 arasındaki yüzdelik sıralarla 1, 50 ve 99 noktalarında örtüşecek biçimde kurulmuştur; bu, yaklaşık 21,06\'lık standart sapma gerektirir.'),
  ('Çeyrekler açıklığının kırılma noktası yaklaşık yüzde kaçtır?', '%25', ['%50', '%0', '%10'], 'Bir uçtaki gözlemlerin %25\'inden fazlası bozulursa ilgili çeyrek de sınırsız kayabilir; bu yüzden IQR\'nin kırılma noktası %25\'tir.'),
  ('Ali\'nin puanından düşük alanlar, A sınıfında (Ali dâhil 30 kişi) 24 kişi, B sınıfında (20 kişi) 18 kişidir; eşit puan yoktur. İki sınıf birleşince Ali\'den düşük alanların toplam öğrenci sayısına oranı yüzde kaçtır?', '%84', ['%85', '%82', '%90'], 'Ali\'den düşük alanların sayısı 24 + 18 = 42, toplam öğrenci 50\'dir: 42/50 = %84. Sınıf yüzdelik sıraları (%80 ve %90) basitçe ortalanamaz; sayılar birleştirilmelidir.'),
  ('İki sınavın ham puanları eşit ağırlıkla toplanarak sıralama yapılıyor. Birinci sınavın standart sapması 20, ikincisininki 5\'tir. Sıralamayı hangi sınav daha çok belirler?', 'Standart sapması 20 olan sınav', ['Standart sapması 5 olan sınav', 'İkisi eşit etki eder', 'Ortalaması büyük olan sınav'], 'Toplamın değişkenliğine büyük yayılımlı sınav çok daha fazla katkı yapar; \'eşit ağırlık\' görünse de etkin ağırlık eşit değildir. Eşit etki için önce z-puanına çevirmek gerekir.'),
  ('Sheppard düzeltmesinin uygun olması için verinin hangi özelliği taşıması beklenir?', 'Sürekli olması ve dağılımın uçlarda yavaşça sıfıra inmesi', ['Sınıflayıcı olması', 'Yalnız iki farklı değer içermesi', 'Sınıf genişliklerinin birbirinden çok farklı olması'], 'Düzeltme, sürekli ve düzgün biçimli (uçlarda kuyrukları sönümlenen) dağılımların eşit genişlikli sınıflarla gruplanması varsayımına dayanır; J biçimli ya da kesikli verilerde uygun değildir.'),
  ('Excel\'in PERCENTILE.EXC işlevi 10 gözlemli bir veriye p = 0,05 ile uygulanırsa ne olur?', '#NUM! hatası verir', ['En küçük değeri döndürür', '0 döndürür', 'Medyanı döndürür'], 'EXC yöntemi konumu (n + 1)·p alır ve yalnız 1/(n + 1) ile n/(n + 1) arasındaki p değerlerini kabul eder; 0,05 < 1/11 olduğundan hata verir.'),
  ('0–10 arası tam sayı puan alan beş öğrencinin ortalaması 9\'dur. Medyan puan en az kaç olabilir?', '9', ['8', '7', '10'], 'Toplam 45\'tir. Medyanı küçültmek için en büyük iki puan 10 alınır; kalan üç puanın toplamı 25 olur ve en büyükleri olan medyan en az 9 olmalıdır (ör. 7, 9, 9, 10, 10).'),
  ('Altı pozitif tam sayının ortalaması, medyanı ve tek modu 5\'tir. Bu sayıların açıklığı en çok kaç olabilir?', '12', ['11', '10', '13'], 'Toplam 30\'dur. 1, 1, 5, 5, 5, 13 verisinde medyan (5 + 5)/2 = 5, tek mod 5 (üç kez) ve ortalama 5\'tir; açıklık 12 olur ve daha büyüğü bu koşullarla sağlanamaz.'),
  ('0 değerine 1, 4 değerine 3 ağırlık verilen bir veride ağırlıklı ortalama 3\'tür. Ağırlıklı varyans, Σwᵢ(xᵢ − x̄)²/Σwᵢ, kaçtır?', '3', ['4', '2', '2,25'], '(1·(0 − 3)² + 3·(4 − 3)²)/4 = (9 + 3)/4 = 3.'),
  ('Gruplanmış bir veride 0–10 sınıfında 2, 10–20 sınıfında 3 gözlem vardır. Ham değerler bilinmiyorsa gerçek ortalamanın kesinlikle içinde bulunduğu en dar aralık hangisidir?', '6 ile 16 arasında', ['5 ile 15 arasında', '0 ile 20 arasında', '10 ile 12 arasında'], 'En küçük olası ortalama bütün gözlemler alt sınırdayken (2·0 + 3·10)/5 = 6, en büyüğü üst sınırdayken (2·10 + 3·20)/5 = 16\'dır.'),
];
